	static interface NodeWithText {
		public string getReportText();

		public string collectReportText(Collection<GTreeNode> included, int indent);

		public bool doesIndent();

		public static class Util {
			public static readonly string INDENTATION = "    ";

			public static string collectReportText(GTreeNode cur,
					Collection<GTreeNode> included, int indent) {
				StringBuilder b = new StringBuilder();
				if (cur is NodeWithText) {
					NodeWithText nwt = (NodeWithText) cur;
					string text = nwt.getReportText();
					if (text != null) {
						b.append('\n');
						for (int i = 0; i < indent; i++) {
							b.append(INDENTATION);
						}
						b.append(nwt.getReportText());
					}
					if (nwt.doesIndent()) {
						indent += 1;
					}
				}
				bool doAll = (included == null || !containsAny(included, cur.getChildren()));
				foreach (GTreeNode node in cur.getChildren()) {
					if (node is NodeWithText && (doAll || included.contains(node))) {
						NodeWithText nwt = (NodeWithText) node;

						b.append(nwt.collectReportText(included, indent));
					}
				}
				return b.toString();
			}

			public static bool containsAny(Collection<GTreeNode> included,
					Collection<GTreeNode> allChildren) {
				Set<GTreeNode> res = new();
				res.addAll(included);
				res.retainAll(allChildren);
				return !res.isEmpty();
			}
		}
	}

