class TransferActionListener : ActionListener, PropertyChangeListener {
	private JComponent focusOwner = null;

	public TransferActionListener() {
		KeyboardFocusManager manager = KeyboardFocusManager.getCurrentKeyboardFocusManager();
		manager.addPropertyChangeListener("permanentFocusOwner", this);
	}

	/* @Override */
	public void propertyChange(PropertyChangeEvent e) {
		object o = e.getNewValue();
		if (o is JComponent) {
			focusOwner = (JComponent) o;
		}
		else {
			focusOwner = null;
		}
	}

	/* @Override */
	public void actionPerformed(ActionEvent e) {
		if (focusOwner == null) {
			return;
		}
		string action = e.getActionCommand();
		Action a = focusOwner.getActionMap().get(action);
		if (a != null) {
			a.actionPerformed(new ActionEvent(focusOwner, ActionEvent.ACTION_PERFORMED, null));
		}
	}
}

class HTMLElement {

	// this contains content and elements
	private List<object> contents = new();

	private string name;
	private Map<string, string> attributes = new();

	HTMLElement(string name) {
		this.name = name;
	}

	string getAttribute(string key) {
		return attributes.get(key);
	}

	string putAttribute(string key, string value) {
		return attributes.put(key, value);
	}

	string removeAttribute(string key) {
		return attributes.remove(key);
	}

	HTMLElement addElement(string elementName) {
		HTMLElement newElement = new HTMLElement(elementName);
		contents.add(newElement);
		return newElement;
	}

	void addHTMLContent(string htmlContent) {
		HTMLContent html = new HTMLContent(htmlContent);
		contents.add(html);
	}

	/* @Override */
	public string toString() {
		// this element's opening tag
		StringBuilder sb = new StringBuilder("<" + name);
		foreach (Map.Entry<string, string> ent in attributes.entrySet()) {
			sb.append(" ");
			sb.append(ent.getKey());
			sb.append("=\"");
			sb.append(ent.getValue());
			sb.append("\"");
		}
		sb.append(">");

		foreach (object obj in contents) {
			// either an HTMLElement or an HTMLContent
			sb.append(obj.toString());
		}

		// closing tag
		sb.append("</" + name + ">");
		return sb.toString();
	}

	private class HTMLContent {
		private string content;

		HTMLContent(string content) {
			this.content = content;
		}

		/* @Override */
		public string toString() {
			return content;
		}
	}

